(function(E){ const x = E["exam-10"] = E["exam-10"] || {units:{}}; (x.units = x.units || {})["x10-l2"] = {"id":"x10-l2","patterns":["L2-leisure","TR-ruledout","TR-paraphrase"],"title":{"en":"Listening Part 2: a podcast about a new hobby","tr":"Listening Part 2: yeni bir hobi hakkında podcast","fa":"Listening Part 2: پادکستی درباره‌ی یک سرگرمی تازه"},"objective":{"en":"In this lesson you will learn to follow an expert on a podcast: choose the two ideas they really give, match items to a small box of qualities, and answer single-choice questions.","tr":"Bu derste bir podcast’teki uzmanı takip etmeyi öğreneceksin: gerçekten verdiği iki fikri seçecek, maddeleri küçük bir özellik kutusuyla eşleştirecek ve tek cevaplı soruları cevaplayacaksın.","fa":"در این درس یاد می‌گیری حرف‌های یک متخصص را در پادکست دنبال کنی: دو ایده‌ای را که واقعاً می‌گوید انتخاب کنی، موردها را با یک کادر کوچک از ویژگی‌ها جور کنی و به سؤال‌های تک‌جوابی جواب بدهی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 2: a podcast about a new hobby","tr":"Listening Part 2: yeni bir hobi hakkında podcast","fa":"Listening Part 2: پادکستی درباره‌ی یک سرگرمی تازه"},"objective":{"en":"In this lesson you will learn to follow an expert on a podcast: choose the two ideas they really give, match items to a small box of qualities, and answer single-choice questions.","tr":"Bu derste bir podcast’teki uzmanı takip etmeyi öğreneceksin: gerçekten verdiği iki fikri seçecek, maddeleri küçük bir özellik kutusuyla eşleştirecek ve tek cevaplı soruları cevaplayacaksın.","fa":"در این درس یاد می‌گیری حرف‌های یک متخصص را در پادکست دنبال کنی: دو ایده‌ای را که واقعاً می‌گوید انتخاب کنی، موردها را با یک کادر کوچک از ویژگی‌ها جور کنی و به سؤال‌های تک‌جوابی جواب بدهی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"2"},{"label":{"en":"Task types","tr":"Görev türü","fa":"نوع تمرین"},"value":"3"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: learning to swim as an adult","tr":"Bu sınav: yetişkinken yüzmeyi öğrenmek","fa":"این آزمون: یادگیری شنا در بزرگسالی"},"intro":{"en":"Part 2 is one main speaker giving everyday information. Hobbies, health and events appear regularly, often as a podcast where a host asks short questions and the guest gives advice.","tr":"Part 2, günlük bilgi veren tek bir ana konuşmacıdır. Hobiler, sağlık ve etkinlikler düzenli olarak çıkar; çoğu zaman sunucunun kısa sorular sorduğu, konuğun tavsiye verdiği bir podcast olarak.","fa":"Part 2 یک گوینده‌ی اصلی است که اطلاعات روزمره می‌دهد. سرگرمی، سلامت و رویدادها مرتب می‌آیند، اغلب به شکل پادکستی که مجری سؤال‌های کوتاه می‌پرسد و مهمان توصیه می‌کند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x10-l2-ctx","exam":true,"patterns":["L2-leisure"],"often":{"pattern":"L2-leisure","n":4,"of":40,"label":{"en":"Comes up often in the real exam: 4 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 4’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۴ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"A podcast about taking up a sport","tr":"Bir spora başlamak hakkında bir podcast","fa":"پادکستی درباره‌ی شروع یک ورزش"},"asks":{"en":"A host interviews an expert about starting a new activity as an adult: why people never started, advice for the beginning, the different kinds of activity, how often to practise and what to do next.","tr":"Bir sunucu, yetişkin olarak yeni bir etkinliğe başlamak hakkında bir uzmanla konuşuyor: insanlar neden hiç başlamamış, başlangıç için tavsiyeler, farklı etkinlik türleri, ne sıklıkla çalışılmalı ve sonra ne yapılmalı.","fa":"یک مجری با یک متخصص درباره‌ی شروع یک فعالیت تازه در بزرگسالی مصاحبه می‌کند: چرا آدم‌ها هیچ‌وقت شروع نکرده‌اند، توصیه‌هایی برای شروع، انواع مختلف فعالیت، هر چند وقت یک بار تمرین کنند و قدم بعدی چیست."},"fields":["Why people never started","Advice for the first session","Equipment","Types and what each is good for","How often","Next steps"],"words":[{"a":"never learned","b":"didn’t get the chance as a child","tr":"hiç öğrenmedi","fa":"هیچ‌وقت یاد نگرفت"},{"a":"far from","b":"an hour away / not nearby","tr":"... uzak","fa":"دور از"},{"a":"afraid of","b":"frightened of / anxious about","tr":"... den korkan","fa":"ترسیده از"},{"a":"rare","b":"it hardly ever happens / it rarely comes up","tr":"nadir","fa":"نادر"},{"a":"quiet","b":"not busy / few people around","tr":"sakin","fa":"خلوت"},{"a":"basic","b":"cheap / nothing expensive","tr":"basit","fa":"ساده"},{"a":"all-round exercise","b":"uses the whole body","tr":"tüm vücut egzersizi","fa":"ورزش همه‌جانبه"},{"a":"takes the longest","b":"needs months of practice","tr":"en uzun süren","fa":"از همه طولانی‌تر"},{"a":"exhausted","b":"very tired / worn out","tr":"bitkin","fa":"خسته و از پا افتاده"},{"a":"not enough","b":"too little / you forget what you learned","tr":"yeterli değil","fa":"کافی نیست"},{"a":"complete beginners","b":"people with no experience at all","tr":"tamamen yeni başlayanlar","fa":"کاملاً تازه‌کارها"}],"traps":[{"en":"\"People often assume X, but actually...\" The assumption is a distractor; the answer follows \"actually\".","tr":"\"İnsanlar çoğu zaman X sanır ama aslında...\" Varsayım çeldiricidir; cevap \"actually\"den sonra gelir.","fa":"«مردم اغلب خیال می‌کنند X، اما در واقع...». این تصور گزینه‌ی انحرافی است؛ جواب بعد از «actually» می‌آید."},{"en":"Common advice is mentioned and then doubted: \"a lot of people tell beginners to..., but I’m not so sure\". Do not choose it.","tr":"Yaygın bir tavsiyeden söz edilip sonra kuşkuyla karşılanır: \"birçok kişi yeni başlayanlara ... der ama ben pek emin değilim\". Onu seçme.","fa":"از یک توصیه‌ی رایج حرف زده می‌شود و بعد در آن تردید می‌شود: «خیلی‌ها به تازه‌کارها می‌گویند...، اما من مطمئن نیستم». انتخابش نکن."},{"en":"In a box of three for four items, one letter is used twice. Two items can share the same quality.","tr":"Dört madde için üçlü bir kutuda bir harf iki kez kullanılır. İki madde aynı özelliği paylaşabilir.","fa":"در کادر سه‌تایی برای چهار مورد، یک حرف دو بار به کار می‌رود. دو مورد می‌توانند ویژگی یکسانی داشته باشند."}],"example":{"lines":[["Guest","Some people say yoga is only for flexible people, but that’s not true at all. What I’d say is that it’s the best thing for your back."]],"item":"What does the guest say about yoga? A It is only for flexible people.  B It is good for back problems.","answer":"B","why":{"en":"\"Some people say\" introduces A, and \"not true at all\" rules it out. \"The best thing for your back\" = B.","tr":"\"Some people say\" A’yı getiriyor ve \"hiç doğru değil\" onu eliyor. \"Sırtın için en iyi şey\" = B.","fa":"«بعضی‌ها می‌گویند» A را می‌آورد و «اصلاً درست نیست» ردش می‌کند. «بهترین چیز برای کمرت» یعنی B."}}},{"id":"L2-leisure","ctx":["L2-leisure"],"title":{"en":"Hobbies, health and events","tr":"Hobiler, sağlık ve etkinlikler","fa":"سرگرمی، سلامت و رویدادها"},"asks":{"en":"A presenter talks about a sport, a hobby, a festival or a healthy activity: how to start, what to avoid and what is on offer this year.","tr":"Bir sunucu bir spor, bir hobi, bir festival ya da sağlıklı bir etkinlik hakkında konuşur: nasıl başlanır, nelerden kaçınılır ve bu yıl neler var.","fa":"یک مجری درباره‌ی یک ورزش، یک سرگرمی، یک جشنواره یا یک فعالیت سالم حرف می‌زند: چطور شروع کنی، از چه دوری کنی و امسال چه برنامه‌هایی هست."},"fields":["What advice does the speaker give to beginners?","Which TWO mistakes do people often make?","What is new at this year’s festival?","What is special about each event?"],"words":[{"a":"beginners","b":"if you're just starting","tr":"yeni başlayanlar","fa":"تازه‌کارها"},{"a":"injury","b":"getting hurt","tr":"sakatlık","fa":"آسیب‌دیدگی"},{"a":"equipment","b":"the gear you need","tr":"ekipman","fa":"وسایل"},{"a":"gradually","b":"a little more each week","tr":"yavaş yavaş","fa":"کم‌کم"},{"a":"venue","b":"where it's held","tr":"mekân","fa":"محل برگزاری"},{"a":"line-up","b":"who is performing","tr":"program","fa":"فهرست اجراها"},{"a":"booking essential","b":"you must reserve a place","tr":"rezervasyon şart","fa":"رزرو الزامی"},{"a":"suitable for","b":"fine for / good for","tr":"... için uygun","fa":"مناسبِ"},{"a":"mistake","b":"where people go wrong","tr":"hata","fa":"اشتباه"},{"a":"benefit","b":"what it does for you","tr":"fayda","fa":"فایده"},{"a":"expert","b":"someone who really knows","tr":"uzman","fa":"متخصص"},{"a":"warm up","b":"get your body ready","tr":"ısınmak","fa":"گرم کردن بدن"}],"traps":[{"en":"Advice given as a contrast: \"people think you should..., but in fact...\". The answer follows \"in fact\".","tr":"Zıtlıkla verilen tavsiye: \"insanlar ... gerektiğini sanıyor ama aslında...\". Cevap \"in fact\"ten sonra gelir.","fa":"توصیه با تضاد: «مردم فکر می‌کنند باید...، ولی در واقع...». جواب بعد از «in fact» می‌آید."},{"en":"Choose TWO: two mistakes are listed, and a third thing is mentioned as fine.","tr":"İki seçenek seç: iki hata sayılır, üçüncü bir şeyin sorun olmadığı söylenir.","fa":"انتخاب دو گزینه: دو اشتباه گفته می‌شود و چیز سومی هم گفته می‌شود که اشکالی ندارد."}],"example":{"lines":[["Presenter","Most new runners buy expensive shoes straight away."],["Presenter","That’s not where they go wrong, though."],["Presenter","The real mistake is running too far, too soon."]],"item":"What is the most common mistake?  A buying expensive shoes   B running too far too soon   C running alone","answer":"B","why":{"en":"Expensive shoes are mentioned and then ruled out. \"The real mistake\" gives the answer.","tr":"Pahalı ayakkabılar söyleniyor, sonra eleniyor. \"The real mistake\" cevabı veriyor.","fa":"کفش گران گفته و بعد رد می‌شود. «The real mistake» جواب را می‌دهد."}},"general":true,"patterns":["L2-leisure"],"often":{"pattern":"L2-leisure","n":4,"of":40,"label":{"en":"Comes up often in the real exam: 4 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 4’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۴ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Three task types in one part","tr":"Bir kısımda üç görev türü","fa":"سه نوع تمرین در یک بخش"},"body":{"en":"Questions 11-12 and 13-14: choose TWO letters, A-E. Questions 15-18: match four items to a box of three, A-C, so one letter is used twice. Questions 19-20: choose A, B or C. There is a pause before Question 15.","tr":"Soru 11-12 ve 13-14: A-E arasından İKİ harf seç. Soru 15-18: dört maddeyi üçlü bir kutuyla (A-C) eşleştir; bir harf iki kez kullanılır. Soru 19-20: A, B ya da C’yi seç. Soru 15’ten önce bir ara vardır.","fa":"سؤال‌های ۱۱-۱۲ و ۱۳-۱۴: دو حرف از A تا E انتخاب کن. سؤال‌های ۱۵ تا ۱۸: چهار مورد را با یک کادر سه‌تایی (A تا C) جور کن، پس یک حرف دو بار می‌آید. سؤال‌های ۱۹ و ۲۰: A، B یا C را انتخاب کن. قبل از سؤال ۱۵ یک مکث هست."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Notice how each task changes: when the questions move from pairs to a box, the topic usually changes too.","tr":"Her görevin nasıl değiştiğine dikkat et: sorular çiftlerden kutuya geçince konu da genelde değişir.","fa":"دقت کن هر تمرین چطور عوض می‌شود: وقتی سؤال‌ها از جفت به کادر می‌رسند، معمولاً موضوع هم عوض می‌شود."},{"en":"For choose TWO, tick only what the guest recommends or confirms; cross out what she doubts.","tr":"İKİ seçmeli sorularda yalnızca konuğun önerdiğini ya da onayladığını işaretle; kuşkuyla baktığının üstünü çiz.","fa":"در «دو تا انتخاب کن» فقط چیزی را علامت بزن که مهمان توصیه یا تأیید می‌کند؛ چیزی را که در آن تردید دارد خط بزن."},{"en":"For the box, learn the three qualities by heart before the pause ends.","tr":"Kutu için üç özelliği ara bitmeden ezberle.","fa":"برای کادر، سه ویژگی را قبل از تمام شدن مکث حفظ کن."},{"en":"For the last single choices, listen for the guest’s final recommendation, not the first idea.","tr":"Son tek seçimler için ilk fikri değil, konuğun son önerisini dinle.","fa":"برای سؤال‌های تک‌جوابی آخر، به توصیه‌ی نهایی مهمان گوش بده، نه ایده‌ی اول."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Advice that is mentioned but not given","tr":"Söylenen ama verilmeyen tavsiye","fa":"توصیه‌ای که گفته می‌شود اما داده نمی‌شود"},"table":{"headers":{"en":["You hear","It means"],"tr":["Duyduğun","Anlamı"],"fa":["می‌شنوی","یعنی"]},"rows":[["A lot of people tell beginners to..., but I’m not so sure.","not her advice"],["You don’t need anything expensive.","expensive equipment is ruled out"],["The one thing I do recommend is...","this is her advice"],["People imagine..., but most...","the imagined idea is wrong"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One single choice, step by step","tr":"Bir tek seçim, adım adım","fa":"یک سؤال تک‌جوابی، قدم به قدم"},"instruction":"Choose the correct letter, A, B or C.","item":"When does the coach say beginners should run? A early in the morning  B after work  C at lunchtime","lines":[["Coach","Lots of people swear by early mornings, and that’s fine if you’re a morning person. Lunchtime is often too rushed. For most beginners, though, the best time is after work, when you need to clear your head."]],"answer":"B","walk":[{"en":"The question asks what the coach recommends for most beginners.","tr":"Soru, koçun çoğu yeni başlayan için ne önerdiğini soruyor.","fa":"سؤال می‌پرسد مربی برای بیشترِ تازه‌کارها چه توصیه‌ای دارد."},{"en":"Mornings suit only \"morning people\"; lunchtime is \"too rushed\".","tr":"Sabahlar yalnızca \"sabah insanlarına\" uyuyor; öğle \"fazla telaşlı\".","fa":"صبح فقط به درد «آدم‌های صبح» می‌خورد؛ ظهر «خیلی شلوغ و عجولانه» است."},{"en":"\"For most beginners, though, the best time is after work\": B.","tr":"\"Ama çoğu yeni başlayan için en iyi zaman iş çıkışı\": B.","fa":"«اما برای بیشترِ تازه‌کارها بهترین زمان بعد از کار است»: B."}]},"quick":{"prompt":"\"Some people buy expensive trainers straight away, but honestly, any comfortable pair will do at the start.\" What is the advice?","options":["Buy expensive trainers.","Run without shoes.","Use any comfortable shoes at first."],"correct":2,"why":{"en":"Buying expensive trainers is what \"some people\" do; \"honestly, any comfortable pair will do\" is the advice.","tr":"Pahalı spor ayakkabı almak \"bazı insanların\" yaptığı şey; tavsiye \"aslında rahat herhangi bir çift yeter\".","fa":"خریدن کفش گران کاری است که «بعضی‌ها» می‌کنند؛ توصیه این است: «راستش هر جفت راحتی کافی است»."}},"remember":{"en":"Choose what the guest recommends or confirms, not what other people say or do.","tr":"Başkalarının söylediğini ya da yaptığını değil, konuğun önerdiğini ya da onayladığını seç.","fa":"چیزی را انتخاب کن که مهمان توصیه یا تأیید می‌کند، نه حرف یا کار دیگران را."},"type":"explain","id":"c-x10-l2-e","course":"ielts-exams","exam":"exam-10","unit":"x10-l2"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 2","title":{"en":"Fresh Start: learning to swim as an adult","tr":"Fresh Start: yetişkinken yüzme öğrenmek","fa":"Fresh Start: یادگیری شنا در بزرگسالی"},"timed":7,"ctx":["L2-leisure"],"script":[{"who":"Host","line":"Hello and welcome to Fresh Start, the podcast about taking up something new at any age. This week I'm talking to swimming coach Rangi Walsh, who teaches adults who never learned to swim. Rangi, welcome."},{"who":"Coach","line":"Thanks for having me."},{"who":"Host","line":"I should admit straight away that I only learned to swim when I was thirty-five, so this topic is very close to my heart."},{"who":"Coach","line":"Then you know exactly what my students go through. The first few weeks are the hardest part, and after that most people really start to enjoy it."},{"who":"Host","line":"So, how common is it for adults not to be able to swim?"},{"who":"Coach","line":"Much more common than people think. In some of my classes, half the people are over forty. When I ask them why they never learned, people often assume it must be because of a bad experience at school, but actually that's quite rare. The two reasons I hear most are distance and fear. A lot of my students grew up in places where the nearest pool was an hour away, so lessons just weren't possible. And many had parents who were frightened of water themselves, and passed that fear on without meaning to. Cost, interestingly, hardly ever comes up, because in most areas school lessons used to be free."},{"who":"Host","line":"So what advice would you give someone who's about to have their very first lesson?"},{"who":"Coach","line":"First of all, choose a quiet time at the pool. Mid-morning on a weekday is ideal. There's nothing worse than trying to get your face wet for the first time with teenagers jumping in all around you. And a lot of people tell beginners to bring a friend along for support, but I'm not so sure about that. People end up comparing themselves, and one of them feels left behind."},{"who":"Host","line":"What about equipment?"},{"who":"Coach","line":"You don't need anything expensive. A basic pair of goggles is fine. The one thing I do recommend is practising your breathing at home before you come. Fill a big bowl with water, put your face in, and breathe out slowly through your nose. It sounds silly, but it makes the first lesson far less frightening."},{"who":"Host","line":"Good tip. Now, our listeners will have heard of the different strokes. Could you tell us which ones you'd recommend?"},{"who":"Coach","line":"Sure. Most people want to start with front crawl, because it's what they see on television. It's a wonderful stroke, and in my opinion it gives you the best all-round exercise, because you use your arms, legs and core all at once. It's not where I'd start a nervous swimmer, though."},{"who":"Host","line":"Where would you start?"},{"who":"Coach","line":"With backstroke, surprisingly. Because you're lying on your back, your face stays out of the water the whole time, so people who are anxious about breathing relax very quickly. Butterfly, on the other hand, is something to save for much later. It looks spectacular, but the timing is very difficult, and even good swimmers need months of practice to get it right."},{"who":"Host","line":"And breaststroke?"},{"who":"Coach","line":"Breaststroke's another good one for nervous beginners. You can keep your head up and see where you're going, which a lot of adults find reassuring. It's a bit slow, but that doesn't matter at the start."},{"who":"Host","line":"How often should people practise, once they've started?"},{"who":"Coach","line":"People who are very keen sometimes try to swim every day, and they're exhausted within a fortnight. Once a week isn't really enough, because you forget what you learned. Twice a week is what I'd suggest. That gives your body time to recover, but it's frequent enough to build confidence."},{"who":"Host","line":"And when people have learned the basics, what's the next step?"},{"who":"Coach","line":"I'd really encourage them to join an adult swimming club. People imagine these clubs are full of competitive swimmers, but most of the ones I know have sessions for complete beginners, often in the evening. They're cheaper than private lessons, too, though that's not the main point. The main point is that you're with other adults who've been through the same thing."},{"who":"Host","line":"Rangi, thank you. That's been really encouraging."},{"who":"Coach","line":"My pleasure. And to anyone listening who's thinking about it: it's never too late."}],"groups":[{"instruction":"Questions 11-12. Choose TWO letters, A-E.","qtype":"mcq2","questions":[{"n":11,"n2":12,"kind":"mcq2","prompt":"Which TWO reasons does Rangi give for adults never having learned to swim?","options":["A They had a bad experience at school.","B They lived a long way from a pool.","C Lessons were too expensive.","D Their parents were afraid of water.","E They were too busy with other sports."],"correct":[1,3],"evidence":"The two reasons I hear most are distance and fear","trap":["TR-ruledout","TR-paraphrase"],"why":{"en":"\"Distance and fear\": the pool was an hour away, and parents passed on their own fear. A bad school experience is \"quite rare\", cost \"hardly ever comes up\", and sport is not mentioned.","tr":"\"Mesafe ve korku\": havuz bir saat uzaktaydı, ebeveynler kendi korkularını aktardı. Okulda kötü deneyim \"oldukça nadir\", maliyet \"neredeyse hiç söz konusu olmuyor\", spordan hiç söz edilmiyor.","fa":"«فاصله و ترس»: استخر یک ساعت راه بود و پدر و مادرها ترس خودشان را منتقل کردند. تجربه‌ی بد در مدرسه «خیلی کم پیش می‌آید»، هزینه «تقریباً هیچ‌وقت مطرح نمی‌شود» و از ورزش حرفی نیست."}}]},{"instruction":"Questions 13-14. Choose TWO letters, A-E.","qtype":"mcq2","questions":[{"n":13,"n2":14,"kind":"mcq2","prompt":"Which TWO pieces of advice does Rangi give for a first lesson?","options":["A Go to the pool when it is quiet.","B Buy good-quality goggles.","C Take a friend with you.","D Wear a swimming cap.","E Practise breathing out at home."],"correct":[0,4],"evidence":"First of all, choose a quiet time at the pool","trap":["TR-ruledout"],"why":{"en":"A \"a quiet time at the pool\" and E breathing out into a bowl at home. Basic goggles are fine, she is \"not so sure\" about bringing a friend, and caps are not mentioned.","tr":"A \"havuzda sakin bir saat\" ve E evde bir kâseye nefes vermek. Basit gözlük yeterli, arkadaş götürmek konusunda \"pek emin değil\", bonedan söz edilmiyor.","fa":"A «یک ساعت خلوت در استخر» و E بیرون دادن نفس در کاسه‌ی آب در خانه. عینک ساده کافی است، درباره‌ی آوردن دوست «زیاد مطمئن نیست» و از کلاه شنا حرفی نیست."}}]},{"instruction":"Questions 15-18. What does Rangi say about each of the following swimming strokes? Choose the correct letter, A, B or C. NB You may use any letter more than once.","qtype":"matching","bank":["A It suits nervous beginners.","B It works the whole body better than the others.","C It takes the longest to learn."],"questions":[{"n":15,"kind":"match","prompt":"front crawl","correct":1,"evidence":"it gives you the best all-round exercise","why":{"en":"\"It gives you the best all-round exercise\", but it is \"not where I’d start a nervous swimmer\".","tr":"\"En iyi genel egzersizi sağlıyor\" ama \"çekingen bir yüzücüye onunla başlamam\".","fa":"«بهترین ورزش همه‌جانبه را می‌دهد»، اما «با آن یک شناگر مضطرب را شروع نمی‌کنم»."},"trap":["TR-ruledout"]},{"n":16,"kind":"match","prompt":"backstroke","correct":0,"evidence":"people who are anxious about breathing relax very quickly","why":{"en":"Your face stays out of the water, so \"people who are anxious... relax very quickly\".","tr":"Yüzün sudan dışarıda kalıyor; bu yüzden \"kaygılı olanlar çok çabuk rahatlıyor\".","fa":"صورتت بیرون آب می‌ماند، پس «کسانی که نگران‌اند خیلی زود آرام می‌شوند»."},"trap":["TR-paraphrase"]},{"n":17,"kind":"match","prompt":"butterfly","correct":2,"evidence":"even good swimmers need months of practice to get it right","why":{"en":"\"Even good swimmers need months of practice\" = it takes the longest to learn.","tr":"\"İyi yüzücüler bile aylarca pratik yapmalı\" = öğrenmesi en uzun süren.","fa":"«حتی شناگرهای خوب ماه‌ها تمرین لازم دارند» یعنی یادگیری‌اش از همه طولانی‌تر است."},"trap":["TR-paraphrase"]},{"n":18,"kind":"match","prompt":"breaststroke","correct":0,"evidence":"another good one for nervous beginners","why":{"en":"\"Another good one for nervous beginners\": A is used again.","tr":"\"Çekingen yeni başlayanlar için bir başka iyi seçenek\": A yeniden kullanılıyor.","fa":"«یکی دیگر از گزینه‌های خوب برای تازه‌کارهای مضطرب»: A دوباره به کار می‌رود."},"trap":["TR-paraphrase"]}]},{"instruction":"Questions 19-20. Choose the correct letter, A, B or C.","qtype":"mcq","questions":[{"n":19,"kind":"mcq","prompt":"How often does Rangi suggest beginners should swim?","options":["A every day","B once a week","C twice a week"],"correct":2,"evidence":"Twice a week is what I'd suggest","why":{"en":"Every day leaves people exhausted; once a week \"isn’t really enough\". Twice a week.","tr":"Her gün insanları yoruyor; haftada bir \"aslında yeterli değil\". Haftada iki.","fa":"هر روز آدم را از پا می‌اندازد؛ هفته‌ای یک بار «واقعاً کافی نیست». هفته‌ای دو بار."},"trap":["TR-ruledout"]},{"n":20,"kind":"mcq","prompt":"What does Rangi say about adult swimming clubs?","options":["A Many offer classes for people who have never swum.","B They are mainly for competitive swimmers.","C Their main advantage is the low price."],"correct":0,"evidence":"most of the ones I know have sessions for complete beginners","why":{"en":"\"People imagine\" they are competitive; the low price is \"not the main point\". Most have beginners’ sessions.","tr":"\"İnsanlar\" rekabetçi olduklarını \"sanıyor\"; düşük fiyat \"asıl mesele değil\". Çoğunun yeni başlayanlar için seansları var.","fa":"«مردم خیال می‌کنند» رقابتی‌اند؛ قیمت پایین «نکته‌ی اصلی نیست». بیشترشان جلسه‌هایی برای تازه‌کارها دارند."},"trap":["TR-ruledout","TR-paraphrase"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Host":{"accent":"British (Southern English)","gender":"F","tts":{"engine":"kokoro","voice":"bf_isabella"},"role":"Podcast host"},"Coach":{"accent":"New Zealand","gender":"M","tts":{"engine":"kokoro","voice":"bm_lewis","fallback":true,"note":"New Zealand wanted; no free New Zealand voice yet"},"role":"Swimming coach (guest)"}},"sequence":[{"type":"announcer","text":"Part 2. You will hear a podcast in which a swimming coach gives advice to adults who want to learn to swim. First, you have some time to look at Questions 11 to 14."},{"type":"pause","seconds":30,"note":"reading time, Questions 11-14"},{"type":"announcer","text":"Now listen carefully and answer Questions 11 to 14."},{"type":"sfx","note":"short podcast jingle (2 s) under the host’s first line; studio sound"},{"type":"lines","from":0,"to":9},{"type":"announcer","text":"Before you hear the rest of the podcast, you have some time to look at Questions 15 to 20."},{"type":"pause","seconds":30,"note":"reading time, Questions 15-20"},{"type":"announcer","text":"Now listen and answer Questions 15 to 20."},{"type":"lines","from":10,"to":21},{"type":"announcer","text":"That is the end of Part 2. You now have half a minute to check your answers.","after":30}]},"id":"c-x10-l2-d","course":"ielts-exams","exam":"exam-10","unit":"x10-l2"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"Within a fortnight they’re exhausted.\" A fortnight is...","options":["two days","two weeks","two months"],"correct":1,"why":{"en":"A fortnight = two weeks.","tr":"A fortnight = iki hafta.","fa":"fortnight یعنی دو هفته."}},{"tests":"paraphrase","point":3,"prompt":"Box: \"It takes the longest to learn.\" Which sentence in a podcast matches it?","options":["Even experienced players need years to master it.","It’s the cheapest way to start.","Everyone can do it on the first day."],"correct":0,"why":{"en":"\"Need years to master it\" = it takes the longest to learn.","tr":"\"Ustalaşmak için yıllar gerekir\" = öğrenmesi en uzun süren.","fa":"«برای استاد شدن سال‌ها لازم است» یعنی یادگیری‌اش از همه طولانی‌تر است."}},{"tests":"method","point":2,"prompt":"Questions 15-18 have four items and only three letters. What should you expect?","options":["One item will have no answer","Each letter is used once and one is left","One letter will be the answer twice"],"correct":2,"why":{"en":"Four answers from three letters: one letter repeats.","tr":"Üç harften dört cevap: bir harf tekrar eder.","fa":"چهار جواب از سه حرف: یک حرف تکرار می‌شود."}},{"tests":"trap","point":3,"prompt":"\"A lot of people tell beginners to buy a heart-rate watch, but I’m not convinced. What I always say is: get a good pair of shoes.\" What is the coach’s advice?","options":["Buy a heart-rate watch","Get good shoes","Both"],"correct":1,"why":{"en":"\"I’m not convinced\" rules out the watch; \"what I always say is\" gives the advice.","tr":"\"Pek ikna olmadım\" saati eliyor; \"hep söylediğim şey\" tavsiyeyi veriyor.","fa":"«قانع نشده‌ام» ساعت را رد می‌کند؛ «چیزی که همیشه می‌گویم» توصیه را می‌دهد."}},{"tests":"trap","point":1,"prompt":"\"People imagine you need to be fit to start, but most of my students couldn’t swim a length.\" What is true?","options":["Most students were not fit at the start","You need to be fit to start","Students swim many lengths"],"correct":0,"why":{"en":"\"People imagine\" is the wrong idea; the fact follows \"but\".","tr":"\"People imagine\" yanlış fikir; gerçek \"but\"tan sonra geliyor.","fa":"«people imagine» ایده‌ی غلط است؛ واقعیت بعد از «but» می‌آید."}}],"id":"c-x10-l2-x","course":"ielts-exams","exam":"exam-10","unit":"x10-l2"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
